}

/* Audit Log Table */
.audit-badge {
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 700;
  font-family: 'JetBrains Mono', monospace;
}

/* AI Advisory & Strategic Recommendations Styles */
.ai-filter-pill {
  padding: 6px 14px;
  border-radius: 12px;
  background: var(--bg-main);
  border: 1px solid var(--card-border);
  color: var(--text-muted);
