}

.ai-rec-card:hover {
  transform: translateY(-3px);
  border-color: #FF7A00;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.08);
}

.ai-rec-card.applied {
  border-color: #10B981;
  background: linear-gradient(180deg, rgba(16, 185, 129, 0.05) 0%, var(--card-bg) 100%);
}

.ai-advice-panel {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
